67| <div id="game-wrap">
68|   <canvas id="canvas"></canvas>
69|   <div id="tally">POPS: 0</div>
70|   <button id="clearBtn">Clear</button>
71| </div>
72| <script>
73|   const CARTRIDGE = {
74|     send(type, payload = {}) {
75|       window.parent.postMessage(
76|         { source: "cartridge", v: 1, type, payload },
77|         "*",
78|       );
79|     },
80|   };
81| </script>
82| <script>
83| (function() {
84|   const canvas = document.getElementById("canvas");
85|   const ctx = canvas.getContext("2d");
86|   const tallyEl = document.getElementById("tally");
87|   const clearBtn = document.getElementById("clearBtn");
88| 
89|   let dpr = Math.max(1, window.devicePixelRatio || 1);
90|   let W = 0, H = 0;
91| 
92|   function resize() {
93|     W = window.innerWidth;
94|     H = window.innerHeight;
95|     dpr = Math.max(1, window.devicePixelRatio || 1);
96|     canvas.width = Math.floor(W * dpr);
97|     canvas.height = Math.floor(H * dpr);
98|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
99|     buildGrain();
100|   }
101| 
102|   // Pre-rendered grain tile
103|   let grainCanvas = null;
104|   function buildGrain() {
105|     const size = 128;
106|     grainCanvas = document.createElement("canvas");
107|     grainCanvas.width = size;
108|     grainCanvas.height = size;
109|     const gctx = grainCanvas.getContext("2d");
110|     const imgData = gctx.createImageData(size, size);
111|     for (let i = 0; i < imgData.data.length; i += 4) {
112|       const v = Math.floor(Math.random() * 255);
113|       imgData.data[i] = v;
114|       imgData.data[i + 1] = v;
115|       imgData.data[i + 2] = v;
116|       imgData.data[i + 3] = 255;
117|     }
118|     gctx.putImageData(imgData, 0, 0);
119|   }
120| 
121|   function drawGrain() {
122|     if (!grainCanvas) return;
123|     const pattern = ctx.createPattern(grainCanvas, "repeat");
124|     ctx.save();
125|     ctx.globalAlpha = 0.08;
126|     ctx.fillStyle = pattern;
127|     ctx.fillRect(0, 0, W, H);
128|     ctx.restore();
129|   }
130| 
131|   // Game state
132|   let running = false;
133|   let paused = false;
134|   let tally = 0;
135|   const bubbles = [];
136|   let lastSpawn = 0;
137|   let spawnInterval = 900;
138|   const inks = ["#ff48b0", "#0078bf"];
139| 
140|   function rand(min, max) {
141|     return Math.random() * (max - min) + min;
142|   }
143| 
144|   function spawnBubble() {
145|     const r = rand(24, 46);
146|     bubbles.push({
147|       x: rand(r, W - r),
148|       y: H + r + rand(0, 60),
149|       r: r,
150|       speed: rand(18, 42) / 60,
151|       wobble: rand(0, Math.PI * 2),
152|       wobbleSpeed: rand(0.01, 0.03),
153|       wobbleAmp: rand(4, 14),
154|       ink: inks[Math.floor(Math.random() * inks.length)],
155|       popped: false,
156|       popT: 0,
157|     });
158|   }
159| 
160|   function settle(dt) {
161|     lastSpawn += dt;
162|     if (lastSpawn > spawnInterval && bubbles.length < 40) {
163|       lastSpawn = 0;
164|       spawnBubble();
165|     }
166|     for (let i = bubbles.length - 1; i >= 0; i--) {
167|       const b = bubbles[i];
168|       if (b.popped) {
169|         b.popT += dt;
170|         if (b.popT > 220) bubbles.splice(i, 1);
171|         continue;
172|       }
173|       b.y -= b.speed * dt;
174|       b.wobble += b.wobbleSpeed * dt;
175|       if (b.y < -b.r - 60) {
176|         bubbles.splice(i, 1);
177|       }
178|     }
179|   }
180| 
181|   function drawHalftoneShade(x, y, r, color) {
182|     // subtle halftone dots to fake shading inside bubble
183|     ctx.save();
184|     ctx.beginPath();
185|     ctx.arc(x, y, r, 0, Math.PI * 2);
186|     ctx.clip();
187|     ctx.fillStyle = color;
188|     const step = Math.max(4, r / 5);
189|     for (let yy = y - r; yy < y + r; yy += step) {
190|       for (let xx = x - r; xx < x + r; xx += step) {
191|         const d = Math.hypot(xx - x, yy - y) / r;
192|         if (d > 0.55 && d < 0.95) {
193|           const dotR = step * 0.22;
194|           ctx.beginPath();
195|           ctx.arc(xx, yy, dotR, 0, Math.PI * 2);
196|           ctx.fill();
197|         }
198|       }
199|     }
200|     ctx.restore();
201|   }
202| 
203|   function drawBubble(b) {
204|     const wob = Math.sin(b.wobble) * b.wobbleAmp * 0.15;
205|     const x = b.x + wob;
206|     const y = b.y;
207| 
208|     if (b.popped) {
209|       // pop burst: a few offset shards
210|       const t = b.popT / 220;
211|       const alpha = 1 - t;
212|       ctx.save();
213|       ctx.globalAlpha = Math.max(0, alpha);
214|       ctx.strokeStyle = b.ink;
215|       ctx.lineWidth = 3;
216|       const spikes = 8;
217|       for (let i = 0; i < spikes; i++) {
218|         const ang = (i / spikes) * Math.PI * 2;
219|         const dist = b.r * (0.6 + t * 1.2);
220|         const px = x + Math.cos(ang) * dist;
221|         const py = y + Math.sin(ang) * dist;
222|         ctx.beginPath();
223|         ctx.moveTo(x + Math.cos(ang) * b.r * 0.3, y + Math.sin(ang) * b.r * 0.3);
224|         ctx.lineTo(px, py);
225|         ctx.stroke();
226|       }
227|       ctx.restore();
228|       return;
229|     }
230| 
231|     // misregistration offset layer (second ink slightly offset)
232|     ctx.save();
233|     ctx.globalAlpha = 0.55;
234|     ctx.fillStyle = b.ink === inks[0] ? inks[1] : inks[0];
235|     ctx.beginPath();
236|     ctx.arc(x + 2, y + 2, b.r, 0, Math.PI * 2);
237|     ctx.fill();
238|     ctx.restore();
239| 
240|     // main flat fill
241|     ctx.save();
242|     ctx.fillStyle = b.ink;
243|     ctx.beginPath();
244|     ctx.arc(x, y, b.r, 0, Math.PI * 2);
245|     ctx.fill();
246|     ctx.restore();
247| 
248|     drawHalftoneShade(x, y, b.r, "#fbf7ee");
249| 
250|     // outline
251|     ctx.save();
252|     ctx.strokeStyle = "#5b3a8c";
253|     ctx.lineWidth = 2;
254|     ctx.beginPath();
255|     ctx.arc(x, y, b.r, 0, Math.PI * 2);
256|     ctx.stroke();
257|     ctx.restore();
258|   }
259| 
260|   function drawTitleScreen() {
261|     ctx.fillStyle = "#fbf7ee";
262|     ctx.fillRect(0, 0, W, H);
263| 
264|     // decorative static bubbles
265|     ctx.save();
266|     ctx.globalAlpha = 0.6;
267|     for (let i = 0; i < 6; i++) {
268|       const r = 30 + (i % 3) * 12;
269|       const x = (W / 7) * (i + 1);
270|       const y = H * 0.35 + Math.sin(i) * 40;
271|       ctx.fillStyle = i % 2 === 0 ? "#ff48b0" : "#0078bf";
272|       ctx.beginPath();
273|       ctx.arc(x, y, r, 0, Math.PI * 2);
274|       ctx.fill();
275|     }
276|     ctx.restore();
277| 
278|     ctx.save();
279|     ctx.textAlign = "center";
280|     ctx.fillStyle = "#5b3a8c";
281|     ctx.font = "bold 44px 'Arial Narrow', Arial, sans-serif";
282|     ctx.fillText("POP THE BUBBLES", W / 2, H * 0.55);
283|     ctx.restore();
284| 
285|     const pulse = 0.6 + 0.4 * Math.sin(performance.now() / 300);
286|     ctx.save();
287|     ctx.globalAlpha = pulse;
288|     ctx.textAlign = "center";
289|     ctx.fillStyle = "#ff48b0";
290|     ctx.font = "bold 26px 'Arial Narrow', Arial, sans-serif";
291|     ctx.fillText("TAP TO BEGIN", W / 2, H * 0.65);
292|     ctx.restore();
293| 
294|     drawGrain();
295|   }
296| 
297|   function draw() {
298|     ctx.fillStyle = "#fbf7ee";
299|     ctx.fillRect(0, 0, W, H);
300| 
301|     if (!running) {
302|       drawTitleScreen();
303|       return;
304|     }
305| 
306|     for (const b of bubbles) drawBubble(b);
307| 
308|     if (paused) {
309|       ctx.save();
310|       ctx.fillStyle = "rgba(91,58,140,0.5)";
311|       ctx.fillRect(0, 0, W, H);
312|       ctx.fillStyle = "#fbf7ee";
313|       ctx.textAlign = "center";
314|       ctx.font = "bold 34px 'Arial Narrow', Arial, sans-serif";
315|       ctx.fillText("PAUSED", W / 2, H / 2);
316|       ctx.restore();
317|     }
318| 
319|     drawGrain();
320|   }
321| 
322|   function updateTallyDisplay() {
323|     tallyEl.textContent = "POPS: " + tally;
324|   }
325| 
326|   // Single clear-the-table function: empties bubbles, zeroes tally,
327|   // returns to the pre-start title screen. Called both by the
328|   // visible Clear button and by the host "reset" command.
329|   function clearTable() {
330|     bubbles.length = 0;
331|     tally = 0;
332|     running = false;
333|     paused = false;
334|     updateTallyDisplay();
335|     CARTRIDGE.send("score", { value: 0 });
336|     draw();
337|   }
338| 
339|   function tryPop(px, py) {
340|     for (let i = bubbles.length - 1; i >= 0; i--) {
341|       const b = bubbles[i];
342|       if (b.popped) continue;
343|       const wob = Math.sin(b.wobble) * b.wobbleAmp * 0.15;
344|       const dx = px - (b.x + wob);
345|       const dy = py - b.y;
346|       if (Math.hypot(dx, dy) <= b.r) {
347|         b.popped = true;
348|         b.popT = 0;
349|         tally += 1;
350|         updateTallyDisplay();
351|         CARTRIDGE.send("score", { value: tally });
352|         return true;
353|       }
354|     }
355|     return false;
356|   }
357| 
358|   canvas.style.touchAction = "none";
359|   canvas.addEventListener("pointerdown", (event) => {
360|     event.preventDefault();
361|     if (paused) return;
362|     const rect = canvas.getBoundingClientRect();
363|     const x = event.clientX - rect.left;
364|     const y = event.clientY - rect.top;
365|     if (!running) {
366|       running = true;
367|       CARTRIDGE.send("start");
368|       // seed a few bubbles right away
369|       for (let i = 0; i < 5; i++) spawnBubble();
370|       return;
371|     }
372|     tryPop(x, y);
373|   });
374| 
375|   clearBtn.addEventListener("click", (e) => {
376|     e.stopPropagation();
377|     clearTable();
378|   });
379|   clearBtn.addEventListener("pointerdown", (e) => {
380|     e.stopPropagation();
381|   });
382| 
383|   window.addEventListener("message", (event) => {
384|     const data = event.data;
385|     if (!data || data.source !== "cartridge-host") return;
386|     if (data.type === "pause") paused = true;
387|     if (data.type === "resume") paused = false;
388|     if (data.type === "reset") clearTable();
389|   });
390| 
391|   window.addEventListener("resize", resize);
392| 
393|   let lastTime = performance.now();
394|   function frame(now) {
395|     const dt = Math.min(50, now - lastTime);
396|     lastTime = now;
397|     if (!paused && running) settle(dt);
398|     draw();
399|     requestAnimationFrame(frame);
400|   }
401| 
402|   resize();
403|   draw();
404|   CARTRIDGE.send("boot", { title: "Pop the Bubbles", gameType: "toy-box", lang: "en" });
405|   requestAnimationFrame(frame);
406| })();
407| </script>
408| </body>
409| </html>
